 "content": "def transform(grid):
    out = [row[:] for row in grid]
    height = len(grid)
    width = len(grid[0]) if height else 0
    # Stamp the vertical key [7, 1, 7, 7, 7] centered on each 8 marker.
    for r in range(height):
        for c in range(width):
            if grid[r][c] == 8:
                for dr, color in zip(range(-2, 3), (7, 1, 7, 7, 7)):
                    rr = r + dr
                    if 0 <= rr < height:
                        out[rr][c] = color
    return out
